var STCSS=`.stc{position:relative;overflow:hidden;background:#fff;color:#16163A;font-family:'Calibri','Carlito','Noto Sans Arabic','Segoe UI',Tahoma,sans-serif;box-sizing:border-box;--b:#2D13EA;--o:#FF7800;--bs:#ECE9FF;--os:#FFF1E4;line-height:1.35}
.stc *{box-sizing:border-box;margin:0;padding:0}\n.stc .st-c>*{flex-shrink:0;min-width:0;max-width:100%}
.stc-a4{width:1123px;height:794px}.stc-sq{width:1080px;height:1080px}.stc-pt{width:1080px;height:1350px}
.stc svg{display:inline-block;vertical-align:middle}
.st-fit{overflow:hidden;overflow-wrap:anywhere}
.st-ref{position:absolute;top:58px;inset-inline-end:66px;font-size:14px;color:#6B6B8E;direction:ltr;letter-spacing:.04em}
.st-logo{position:absolute;top:50px;inset-inline-start:64px;height:60px;display:flex;align-items:center}.st-logo img{max-height:60px;max-width:210px;object-fit:contain}
.st-wm{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;font-size:120px;font-weight:800;color:rgba(45,19,234,.08);transform:rotate(-16deg);pointer-events:none;z-index:9}
.st-en{direction:ltr;unicode-bidi:isolate}
.st-ar{direction:rtl;unicode-bidi:isolate}
/* frame: certificates */
.stc-frame .st-border{position:absolute;inset:26px;border:2px solid var(--b);border-radius:8px}
.stc-frame .st-border::after{content:"";position:absolute;inset:9px;border:1px solid rgba(255,120,0,.6);border-radius:4px}
.stc-frame .st-ring1{position:absolute;width:460px;height:460px;border-radius:50%;border:64px solid var(--bs);top:-230px;inset-inline-end:-170px}
.stc-frame .st-ring2{position:absolute;width:260px;height:260px;border-radius:50%;border:18px solid var(--o);bottom:-150px;inset-inline-start:-150px;opacity:.95}
.stc-frame .st-dots{position:absolute;width:150px;height:96px;bottom:150px;inset-inline-end:80px;background-image:radial-gradient(rgba(45,19,234,.28) 2px,transparent 2.5px);background-size:16px 16px}
.stc-frame .st-c{position:absolute;inset:118px 120px 150px;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;gap:12px}
.stc-frame .st-badge{width:66px;height:66px;border-radius:50%;background:var(--o);display:flex;align-items:center;justify-content:center;color:#fff;box-shadow:0 10px 24px -10px rgba(255,120,0,.8)}
.stc-frame .st-badge svg{width:32px;height:32px}
.stc-frame .st-title{font-size:44px;font-weight:700;color:var(--b);line-height:1.15;max-width:860px}
.stc-frame .st-title .st-en{display:block;font-size:26px;font-weight:600;color:#4B3DF0;margin-top:4px}
.stc-frame .st-bar{width:76px;height:5px;border-radius:3px;background:var(--o)}
.stc-frame .st-to{font-size:19px;color:#55557A}
.stc-frame .st-name{font-size:54px;font-weight:700;color:#14143A;line-height:1.18;max-width:880px;max-height:130px}
.stc-frame .st-name .st-en{display:block;font-size:30px;font-weight:600;color:#3A3A60}
.stc-frame .st-role{font-size:19px;color:#55557A;max-width:860px}
.stc-frame .st-body{font-size:21px;line-height:1.65;color:#2B2B4A;max-width:840px;max-height:150px}
.stc-frame .st-body .st-en{display:block;font-size:17px;color:#4A4A6A;margin-top:6px}
.stc-frame .st-foot{position:absolute;bottom:66px;inset-inline:120px;display:flex;justify-content:space-between;align-items:flex-end;font-size:15px;color:#6B6B8E}
.stc-frame .st-foot b{display:block;font-size:18px;color:#14143A;font-weight:700}
/* band: cards with a blue head band */
.stc-band .st-band{position:absolute;inset:0 0 auto 0;height:400px;background:var(--b);overflow:hidden}
.stc-pt.stc-band .st-band{height:500px}
.stc-band .st-band i{position:absolute;border-radius:50%}
.stc-band .st-band i:nth-child(1){width:340px;height:340px;background:var(--o);top:-120px;inset-inline-end:-90px}
.stc-band .st-band i:nth-child(2){width:520px;height:520px;border:3px solid rgba(255,255,255,.25);top:-260px;inset-inline-end:60px}
.stc-band .st-band i:nth-child(3){width:160px;height:160px;background:rgba(255,255,255,.12);bottom:-60px;inset-inline-start:40%}
.stc-band .st-bt{position:absolute;top:110px;inset-inline:90px;color:#fff;font-size:70px;font-weight:800;line-height:1.1;max-height:170px}
.stc-band .st-bt .st-en{display:block;font-size:34px;font-weight:600;opacity:.9;margin-top:6px}
.stc-band .st-photo{position:absolute;top:300px;inset-inline-start:90px;width:200px;height:200px;border-radius:50%;border:10px solid #fff;object-fit:cover;background:var(--bs);box-shadow:0 18px 40px -20px rgba(20,20,60,.5)}
.stc-pt.stc-band .st-photo{top:400px}
.stc-band .st-c{position:absolute;top:470px;inset-inline:90px;bottom:170px;display:flex;flex-direction:column;gap:16px}
.stc-band.st-hasph .st-c{top:540px}
.stc-pt.stc-band .st-c{top:580px}.stc-pt.stc-band.st-hasph .st-c{top:650px}
.stc-band .st-name{font-size:58px;font-weight:800;color:#14143A;line-height:1.15;max-height:140px}
.stc-band .st-name .st-en{display:block;font-size:32px;font-weight:600;color:#3A3A60}
.stc-band .st-role{font-size:24px;color:#55557A}
.stc-band .st-body{font-size:30px;line-height:1.55;color:#2B2B4A;max-height:300px}
.stc-pt.stc-band .st-body{max-height:420px}
.stc-band .st-body .st-en{display:block;font-size:23px;color:#4A4A6A;margin-top:8px}
.stc-band .st-foot{position:absolute;bottom:70px;inset-inline:90px;display:flex;justify-content:space-between;align-items:center;border-top:4px solid var(--o);padding-top:22px;font-size:21px;color:#55557A}
.stc-band .st-foot b{color:#14143A}
.stc-band .st-ref{color:rgba(255,255,255,.75)}
.stc-band .st-logo{background:#fff;border-radius:14px;padding:8px 14px;height:auto}
/* burst: light card with orange and blue circles */
.stc-burst{background:#FFFDFB}
.stc-burst .st-s1{position:absolute;width:560px;height:560px;border-radius:50%;background:var(--os);top:-200px;inset-inline-end:-160px}
.stc-burst .st-s2{position:absolute;width:300px;height:300px;border-radius:50%;background:var(--o);top:-90px;inset-inline-end:-40px}
.stc-burst .st-s3{position:absolute;width:380px;height:380px;border-radius:50%;border:56px solid var(--bs);bottom:-170px;inset-inline-start:-140px}
.stc-burst .st-s4{position:absolute;width:120px;height:120px;border-radius:50%;background:var(--b);bottom:120px;inset-inline-end:110px;opacity:.9}
.stc-burst .st-c{position:absolute;inset:200px 100px 190px;display:flex;flex-direction:column;justify-content:center;gap:18px}
.stc-pt.stc-burst .st-c{inset:240px 100px 220px}
.stc-burst .st-icon{width:84px;height:84px;border-radius:24px;background:var(--b);color:#fff;display:flex;align-items:center;justify-content:center}
.stc-burst .st-icon svg{width:42px;height:42px}
.stc-burst .st-title{font-size:72px;font-weight:800;color:var(--b);line-height:1.1;max-height:170px}
.stc-burst .st-title .st-en{display:block;font-size:34px;font-weight:600;color:#4B3DF0}
.stc-burst .st-bar{width:96px;height:7px;border-radius:4px;background:var(--o)}
.stc-burst .st-name{font-size:50px;font-weight:800;color:#14143A;line-height:1.15;max-height:125px}
.stc-burst .st-name .st-en{display:block;font-size:28px;font-weight:600;color:#3A3A60}
.stc-burst .st-photo{width:150px;height:150px;border-radius:50%;object-fit:cover;border:6px solid #fff;box-shadow:0 14px 30px -16px rgba(20,20,60,.5)}
.stc-burst .st-body{font-size:30px;line-height:1.55;color:#2B2B4A;max-height:280px}
.stc-pt.stc-burst .st-body{max-height:400px}
.stc-burst .st-body .st-en{display:block;font-size:23px;color:#4A4A6A;margin-top:8px}
.stc-burst .st-foot{position:absolute;bottom:72px;inset-inline:100px;display:flex;justify-content:space-between;align-items:center;font-size:21px;color:#55557A}
.stc-burst .st-foot b{color:#14143A}
.stc-burst .st-note{font-size:17px;color:#6B6B8E}`;
